with flattened as (select id, coupon_codes, inline(items) from carts) select case when price >= 209 then 'LARGE' else 'SMALL' end as price_tier, promo, case when qty >= 4 then 'HIGH' else 'LOW' end as qty_tier, count(distinct promo) as distinct_promos, max(product_id) filter (where promo = 'BUNDLE') as bundle_max_product_id from flattened group by case when price >= 209 then 'LARGE' else 'SMALL' end, promo, case when qty >= 4 then 'HIGH' else 'LOW' end having max(product_id) filter (where promo = 'BUNDLE') > 0;
